if (loginBtn) {
    loginBtn.addEventListener('click', function() { openAuthModal(true); });
}
if (registerBtn) {
    registerBtn.addEventListener('click', function() { openAuthModal(false); });
}

function openAuthModal(login) {
    isLoginMode = login;
    if (authModal) authModal.classList.add('active');
    if (authModalTitle) {
        authModalTitle.innerHTML = login ?
            '<i class="fas fa-sign-in-alt"></i> تسجيل الدخول' :
            '<i class="fas fa-user-plus"></i> إنشاء حساب';
    }
    if (authSubmitBtn) {
        authSubmitBtn.innerHTML = login ?
            '<i class="fas fa-sign-in-alt"></i> دخول' :
            '<i class="fas fa-user-plus"></i> إنشاء حساب';
    }
    if (authSwitchBtn) {
        authSwitchBtn.textContent = login ?
            'ليس لديك حساب؟ سجل الآن' :
            'لديك حساب؟ سجل دخول';
    }
    // إظهار/إخفاء حقل الاسم المعروض واسم المستخدم
    if (authNameGroup) authNameGroup.style.display = login ? 'none' : 'block';
    const usernameGroup = document.getElementById('authUsernameGroup');
    if (usernameGroup) usernameGroup.style.display = login ? 'none' : 'block';
    if (authDisplayName) authDisplayName.required = !login;
    if (authForm) authForm.reset();

    // تغيير placeholder حقل البريد
    const emailInput = document.getElementById('authEmail');
    if (emailInput) {
        emailInput.placeholder = login ? 'البريد الإلكتروني أو اسم المستخدم' : 'البريد الإلكتروني';
    }
}

if (authSwitchBtn) {
    authSwitchBtn.addEventListener('click', function() {
        openAuthModal(!isLoginMode);
    });
}

if (authForm) {
    authForm.addEventListener('submit', async function(e) {
        e.preventDefault();
        var email = authEmail ? authEmail.value.trim() : '';
        var password = authPassword ? authPassword.value : '';
        var displayName = authDisplayName ? authDisplayName.value.trim() : '';
        if (!email || !password) {
            showToast('يرجى إدخال البريد الإلكتروني وكلمة المرور', 'error');
            return;
        }
        var success = false;
        if (isLoginMode) {
            success = await loginUser(email, password);
        } else {
const usernameInput = document.getElementById('authUsernameInput');
const username = usernameInput ? usernameInput.value.trim() : '';
success = await registerUser(email, password, displayName, username);        }
        if (success) {
              isNewUser = false;

            if (authModal) authModal.classList.remove('active');
            updateUI();
            await loadAllData();
        }
    });
}

if (logoutBtn) {
    logoutBtn.addEventListener('click', function() {
        if (confirm('هل أنت متأكد من تسجيل الخروج؟')) {
            logoutUser();
            updateUI();
            loadAllData();
        }
    });
}

// ============================================================
//  AUTH STATE OBSERVER
// ============================================================
auth.onAuthStateChanged(async function(user) {
    if (user) {
        currentUser = user;
        try {
            await loadUserData(user.uid);
            
            // التحقق من الحظر
            if (currentUserData && currentUserData.banned === true) {
                // عرض صفحة الحظر فقط
                showBannedPage();
                
                // إخفاء جميع الروابط في القائمة العلوية
                hideAllNavLinks();
                
                // عرض اسم المستخدم والبريد في صفحة الحظر
                updateBannedPageInfo();
                
                // تعطيل جميع التفاعلات
                disableAllInteractions();
                
                return; // منع أي تحميل إضافي
            }
            
            // المستخدم غير محظور - تحميل البيانات كاملة
            updateUI();
            await loadAllData();
            showPage('posts');
            
        } catch (error) {
            console.error('Error loading user data:', error);
            showToast('حدث خطأ في تحميل بيانات المستخدم', 'error');
        }
    } else {
        // مستخدم غير مسجل
        currentUser = null;
        currentUserData = null;
        isAdmin = false;
        isProfileRequired = false;
        updateUI();
        courses = [];
        colleges = [];
        allSpecialties = [];
        users = [];
        allUsers = [];
        renderCourses();
        renderUsers();
        showPage('posts');
        hideNavLinksForGuest();
    }
});


