    if (title) {
        title.innerHTML = '<i class="fas fa-gift" style="color:#f59e0b;"></i> إهداء نقاط إلى ' + escapeHtml(user.displayName || 'المستخدم');
    }

    var maxPoints = Math.min(100, result.points);
